// Vant admin tutorial: builds the whole video in After Effects as native layers.
//
// How to run: keep this file next to the "assets" folder, then in After Effects choose
// File > Scripts > Run Script File... and pick VantAdminTutorial.jsx.
// It creates a folder "Vant Admin Tutorial" with the main comp "Vant Admin Tutorial" and its precomps.
//
// For Bangla text: Preferences > Type > "South Asian and Middle Eastern" text engine (restart AE once),
// and the Hind Siliguri font (Medium / SemiBold / Bold) and Inter (Medium / SemiBold) installed.
//
// Generated by ae/export.mjs from VantAdminTutorial.html. Edit the HTML project and re-export
// rather than editing the data below by hand.
(function () {
    var D = /*DATA*/null;

    var FPS = D.FPS, DUR = D.D;
    var T = D.tracks;
    var ROOT = File($.fileName).parent;
    var FONT = { bn: "HindSiliguri-SemiBold", bnBold: "HindSiliguri-Bold", bnMedium: "HindSiliguri-Medium", en: "Inter-Medium", enSemi: "Inter-SemiBold" };

    // ---------------------------------------------------------------- helpers
    function hex(c) {
        if (c.charAt(0) === "#") {
            return [parseInt(c.substr(1, 2), 16) / 255, parseInt(c.substr(3, 2), 16) / 255, parseInt(c.substr(5, 2), 16) / 255];
        }
        var m = c.match(/(\d+(\.\d+)?)/g);
        return [m[0] / 255, m[1] / 255, m[2] / 255];
    }
    function hasBangla(s) { return /[ঀ-৿]/.test(s); }
    function tr(L) { return L.property("ADBE Transform Group"); }

    // Sets keyframes from [[frame, value], ...]; a single entry becomes a plain value.
    function keyed(prop, list, map) {
        if (!list || !list.length) return;
        if (list.length === 1) { prop.setValue(map ? map(list[0][1]) : list[0][1]); return; }
        var times = [], values = [];
        for (var i = 0; i < list.length; i++) { times.push(list[i][0] / FPS); values.push(map ? map(list[i][1]) : list[i][1]); }
        prop.setValuesAtTimes(times, values);
    }
    // Combines two recorded series (e.g. width and height) into one 2D property.
    function keyed2(prop, a, b, map) {
        var frames = {}, i;
        for (i = 0; i < a.length; i++) frames[a[i][0]] = 1;
        for (i = 0; i < b.length; i++) frames[b[i][0]] = 1;
        var fs = [];
        for (var f in frames) fs.push(+f);
        fs.sort(function (x, y) { return x - y; });
        function at(list, f) {
            if (list.length === 1 || f <= list[0][0]) return list[0][1];
            for (var k = 1; k < list.length; k++) {
                if (f <= list[k][0]) {
                    var p = list[k - 1], q = list[k];
                    return p[1] + (q[1] - p[1]) * (f - p[0]) / (q[0] - p[0]);
                }
            }
            return list[list.length - 1][1];
        }
        if (fs.length === 1) { prop.setValue(map(at(a, fs[0]), at(b, fs[0]))); return; }
        var times = [], values = [];
        for (i = 0; i < fs.length; i++) { times.push(fs[i] / FPS); values.push(map(at(a, fs[i]), at(b, fs[i]))); }
        prop.setValuesAtTimes(times, values);
    }
    // Opacity is 0-100 in After Effects; eased values in the HTML can overshoot slightly, so clamp.
    function pct(v) { return Math.max(0, Math.min(100, v)); }
    function opacity(L, list, factor) { keyed(tr(L).property("ADBE Opacity"), list, function (v) { return pct(v * 100 * (factor || 1)); }); }
    // Position with X and Y as separate properties (no curved motion paths between dense keys).
    function position(L, xs, ys, fx, fy) {
        var p = tr(L).property("ADBE Position");
        p.dimensionsSeparated = true;
        keyed(tr(L).property("ADBE Position_0"), xs, fx);
        keyed(tr(L).property("ADBE Position_1"), ys, fy);
    }
    function still(v) { return [[0, v]]; }

    function shape(comp, name, kind, w, h, r, o) {
        o = o || {};
        var L = comp.layers.addShape();
        L.name = name;
        var g = L.property("ADBE Root Vectors Group").addProperty("ADBE Vector Group");
        var c = g.property("ADBE Vectors Group");
        var s;
        if (kind === "ellipse") {
            s = c.addProperty("ADBE Vector Shape - Ellipse");
            s.property("ADBE Vector Ellipse Size").setValue([w, h]);
        } else {
            s = c.addProperty("ADBE Vector Shape - Rect");
            s.property("ADBE Vector Rect Size").setValue([w, h]);
            s.property("ADBE Vector Rect Roundness").setValue(r || 0);
        }
        if (o.stroke) {
            var st = c.addProperty("ADBE Vector Graphic - Stroke");
            st.property("ADBE Vector Stroke Color").setValue(hex(o.stroke));
            st.property("ADBE Vector Stroke Width").setValue(o.strokeW || 2);
            if (o.strokeOpacity != null) st.property("ADBE Vector Stroke Opacity").setValue(o.strokeOpacity);
        }
        if (o.fill) {
            var f = c.addProperty("ADBE Vector Graphic - Fill");
            f.property("ADBE Vector Fill Color").setValue(hex(o.fill));
            if (o.fillOpacity != null) f.property("ADBE Vector Fill Opacity").setValue(o.fillOpacity);
        }
        tr(L).property("ADBE Anchor Point").setValue([0, 0]);
        if (o.at) tr(L).property("ADBE Position").setValue(o.at);
        return L;
    }
    // The size property of a layer made by shape(): first item inside its first group.
    function sizeOf(L) {
        var item = L.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").property(1);
        return item.property(item.matchName === "ADBE Vector Shape - Ellipse" ? "ADBE Vector Ellipse Size" : "ADBE Vector Rect Size");
    }
    function text(comp, name, str, font, size, color, at, o) {
        o = o || {};
        var L = comp.layers.addText(str);
        L.name = name;
        var tp = L.property("ADBE Text Properties").property("ADBE Text Document");
        var td = tp.value;
        try { td.resetCharStyle(); td.resetParagraphStyle(); } catch (e) {}
        td.font = font;
        td.fontSize = size;
        td.applyFill = true;
        td.fillColor = hex(color);
        td.applyStroke = false;
        td.justification = o.center ? ParagraphJustification.CENTER_JUSTIFY : (o.right ? ParagraphJustification.RIGHT_JUSTIFY : ParagraphJustification.LEFT_JUSTIFY);
        if (o.tracking) td.tracking = o.tracking;
        tp.setValue(td);
        if (at) tr(L).property("ADBE Position").setValue(at);
        return L;
    }
    function solid(comp, name, color, w, h) {
        var L = comp.layers.addSolid(hex(color), name, w, h, 1, DUR);
        return L;
    }
    function ramp(L, a, colA, b, colB, radial) {
        var fx = L.property("ADBE Effect Parade").addProperty("ADBE Ramp");
        fx.property("ADBE Ramp-0001").setValue(a);
        fx.property("ADBE Ramp-0002").setValue(hex(colA));
        fx.property("ADBE Ramp-0003").setValue(b);
        fx.property("ADBE Ramp-0004").setValue(hex(colB));
        fx.property("ADBE Ramp-0005").setValue(radial ? 2 : 1);
    }
    function shadow(L, opacity255, dist, soft) {
        var fx = L.property("ADBE Effect Parade").addProperty("ADBE Drop Shadow");
        fx.property("ADBE Drop Shadow-0002").setValue(opacity255);
        fx.property("ADBE Drop Shadow-0003").setValue(180);
        fx.property("ADBE Drop Shadow-0004").setValue(dist);
        fx.property("ADBE Drop Shadow-0005").setValue(soft);
    }
    // Rounded-rectangle mask (for the phone screen corners).
    function roundMask(L, w, h, r) {
        var k = r * 0.5523, sh = new Shape();
        sh.vertices = [[r, 0], [w - r, 0], [w, r], [w, h - r], [w - r, h], [r, h], [0, h - r], [0, r]];
        sh.inTangents = [[-k, 0], [0, 0], [0, -k], [0, 0], [k, 0], [0, 0], [0, k], [0, 0]];
        sh.outTangents = [[0, 0], [k, 0], [0, 0], [0, k], [0, 0], [-k, 0], [0, 0], [0, -k]];
        sh.closed = true;
        var m = L.property("ADBE Mask Parade").addProperty("ADBE Mask Atom");
        m.property("ADBE Mask Shape").setValue(sh);
    }
    function holdAll(prop) {
        for (var k = 1; k <= prop.numKeys; k++) prop.setInterpolationTypeAtKey(k, KeyframeInterpolationType.HOLD);
    }
    function footage(rel) {
        var f = new File(ROOT.fsName + "/assets/" + rel);
        if (!f.exists) throw new Error("Missing file: " + f.fsName + "\nKeep VantAdminTutorial.jsx next to the assets folder.");
        var item = app.project.importFile(new ImportOptions(f));
        item.parentFolder = files;
        return item;
    }
    function precomp(name, w, h) {
        var c = app.project.items.addComp(name, w, h, 1, DUR, FPS);
        c.parentFolder = folder;
        return c;
    }
    function place(comp, item, name, anchor, at, scale) {
        var L = comp.layers.add(item);
        L.name = name;
        tr(L).property("ADBE Anchor Point").setValue(anchor);
        if (at) tr(L).property("ADBE Position").setValue(at);
        if (scale) tr(L).property("ADBE Scale").setValue([scale, scale]);
        return L;
    }

    // ---------------------------------------------------------------- start
    app.beginUndoGroup("Build Vant admin tutorial");
    var folder = app.project.items.addFolder("Vant Admin Tutorial");
    var files = app.project.items.addFolder("Vant files");
    files.parentFolder = folder;

    // ---------------- browser content: the captured admin screens, 1440 x 864 ----------------
    var vp = precomp("Browser viewport", 1440, 864);
    solid(vp, "White", "#ffffff", 1440, 864);
    var nt = solid(vp, "New tab", "#f7f5f3", 1440, 864);
    opacity(nt, T["newtab"].o);
    for (var name in T) {
        if (name.indexOf("scr-") !== 0) continue;
        var id = T[name].extra.id;
        var S = place(vp, footage("screens/" + id + ".jpg"), id, [0, 0], [0, 0], 50);
        position(S, still(0), T[name].y);
        opacity(S, T[name].o);
    }
    var side = place(vp, footage("screens/sidebar.jpg"), "Menu (scrolling)", [0, 0], [0, 76], 50);
    position(side, still(0), T["sidebar"].y, null, function (v) { return 76 + v; });
    opacity(side, T["sidebar"].o);

    // ---------------- browser window: tabs, address bar, viewport, 1440 x 940 ----------------
    var bw = precomp("Browser window", 1440, 940);
    solid(bw, "Window", "#ffffff", 1440, 940);
    place(bw, vp, "Viewport", [0, 0], [0, 76]);
    shape(bw, "Toolbar line", "rect", 1440, 1, 0, { fill: "#e5e5e5", at: [720, 75.5] });
    shape(bw, "Address pill", "rect", 1300, 26, 13, { fill: "#f1f1f1", at: [746, 58] });
    text(bw, "Back", "←", FONT.enSemi, 15, "#777777", [18, 63]);
    text(bw, "Forward", "→", FONT.enSemi, 15, "#777777", [44, 63]);
    text(bw, "Reload", "↻", FONT.enSemi, 15, "#777777", [70, 63]);
    shape(bw, "Tab bar", "rect", 1440, 40, 0, { fill: "#e9e6e4", at: [720, 20] });
    shape(bw, "Close", "ellipse", 12, 12, 0, { fill: "#ff5f57", at: [22, 20] });
    shape(bw, "Minimise", "ellipse", 12, 12, 0, { fill: "#febc2e", at: [42, 20] });
    shape(bw, "Zoom", "ellipse", 12, 12, 0, { fill: "#28c840", at: [62, 20] });
    shape(bw, "Tab", "rect", 270, 34, 10, { fill: "#ffffff", at: [227, 23] });
    place(bw, footage("vant-mark.png"), "Tab icon", [0, 0], [104, 15], 4);
    var nm;
    for (nm in T) {
        var ex = T[nm].extra;
        if (!ex || !ex.kind) continue;
        var isUrl = ex.kind === "url";
        var L = text(bw, (isUrl ? "URL " : "Tab title ") + nm.replace(/^(url|ttl)-/, ""), ex.text,
            hasBangla(ex.text) ? FONT.bnMedium : FONT.en, isUrl ? 13.5 : 13, nm === "url-newtab" ? "#999999" : (isUrl ? "#444444" : "#333333"),
            isUrl ? [112, 63] : [128, 28]);
        opacity(L, T[nm].o);
    }

    // ---------------- laptop display: wallpaper, menu bar, browser, dock, 1600 x 1000 ----------------
    var dp = precomp("Laptop display", 1600, 1000);
    var wall = solid(dp, "Wallpaper", "#7a2a3a", 1600, 1000);
    ramp(wall, [300, 0], "#7a2a3a", [1300, 1000], "#2a0a12", false);
    var mb = shape(dp, "Menu bar", "rect", 1600, 28, 0, { fill: "#ffffff", fillOpacity: 14, at: [800, 14] });
    var mbt = text(dp, "Menu bar items", "    Finder    File    Edit    View    Window", FONT.enSemi, 14, "#ffffff", [26, 19]);
    var mbc = text(dp, "Menu bar clock", "Tue 14:30", FONT.enSemi, 14, "#ffffff", [1578, 19], { right: true });
    opacity(mb, T["menubar"].o); opacity(mbt, T["menubar"].o); opacity(mbc, T["menubar"].o);
    var bl = place(dp, bw, "Browser", [720, 940], [800, 992]);
    position(bl, still(800), T["browser"].y, null, function (v) { return 992 + v; });
    keyed(tr(bl).property("ADBE Scale"), T["browser"].s, function (v) { return [v * 100, v * 100]; });
    opacity(bl, T["browser"].o);
    shadow(bl, 70, 30, 80);
    var dockParts = [shape(dp, "Dock", "rect", 440, 72, 22, { fill: "#ffffff", fillOpacity: 22, stroke: "#ffffff", strokeOpacity: 35, strokeW: 1, at: [800, 954] })];
    var appColors = ["#2f8cff", "#ffcc33", "#ffffff", "#ff3b30", "#8e5cf7"];
    for (var a = 0; a < 5; a++) dockParts.push(shape(dp, "Dock app " + (a + 1), "rect", 52, 52, 13, { fill: appColors[a], at: [580 + 14 + a * 84 + 26, 918 + 10 + 26] }));
    dockParts.push(shape(dp, "Browser icon", "ellipse", 36, 36, 0, { fill: "#2f8cff", at: [788, 954] }));
    for (a = 0; a < dockParts.length; a++) opacity(dockParts[a], T["dock"].o);

    // ---------------- phone screen, 360 x 779 ----------------
    var ps = precomp("Phone screen", 360, 779);
    var pw = solid(ps, "Phone wallpaper", "#7a2a3a", 360, 779);
    ramp(pw, [60, 0], "#7a2a3a", [300, 779], "#2a0a12", false);
    var tiles = ["#2f8cff", "#ffcc33", "#34c759", "#ff3b30", "#8e5cf7", "#ff9500", "#5ac8fa", "#ff2d55", "#30b0c7", "#a2845e", "#64d2ff", "#bf5af2"];
    for (var t = 0; t < 12; t++) shape(ps, "App " + (t + 1), "rect", 60, 60, 15, { fill: tiles[t], at: [60 + (t % 4) * 80, 140 + Math.floor(t / 4) * 92] });
    shape(ps, "Phone dock", "rect", 312, 84, 30, { fill: "#ffffff", fillOpacity: 22, at: [180, 710] });
    for (t = 0; t < 4; t++) shape(ps, "Dock app " + (t + 1), "rect", 60, 60, 15, { fill: tiles[t * 3], at: [72 + t * 74, 710] });
    var pimg = place(ps, footage("screens/dashboard-phone.jpg"), "Admin on phone", [0, 0], [0, 0], 46.154);
    opacity(pimg, T["phoneImg"].o);

    // ---------------- main comp ----------------
    var main = app.project.items.addComp("Vant Admin Tutorial", 1920, 1080, 1, DUR, FPS);
    main.parentFolder = folder;
    var bg = solid(main, "Background", "#6b1f2e", 1920, 1080);
    ramp(bg, [960, 454], "#6b1f2e", [960 + 1150, 454], "#1c0509", true);

    // Everything on the desk hangs from one null: the camera moves are keyframes on this null.
    var cam = main.layers.addNull(DUR);
    cam.name = "CAMERA (move me)";
    tr(cam).property("ADBE Anchor Point").setValue([0, 0]);
    tr(cam).property("ADBE Position").setValue([0, 0]);
    var onDesk = [];
    function desk(L) { L.parent = cam; onDesk.push(L); return L; }

    var lid = desk(shape(main, "Laptop lid", "rect", 1644, 1044, 38, { fill: "#0d0d10", stroke: "#3a3a40", strokeW: 2, at: [800, 500] }));
    shadow(lid, 75, 60, 120);
    desk(place(main, dp, "Laptop display", [0, 0], [0, 0]));
    desk(shape(main, "Notch", "rect", 120, 22, 12, { fill: "#0d0d10", at: [800, -11] }));
    desk(shape(main, "Laptop base", "rect", 1920, 30, 14, { fill: "#b9babf", at: [800, 1037] }));
    desk(shape(main, "Laptop base lip", "rect", 160, 10, 5, { fill: "#a9aab0", at: [800, 1027] }));
    var phone = desk(shape(main, "Phone body", "rect", 400, 819, 64, { fill: "#111111", stroke: "#4a4a50", strokeW: 3, at: [1900, 569.5] }));
    shadow(phone, 75, 50, 100);
    var psl = desk(place(main, ps, "Phone screen", [0, 0], [1720, 180]));
    roundMask(psl, 360, 779, 46);
    desk(shape(main, "Phone island", "rect", 120, 34, 17, { fill: "#000000", at: [1900, 209] }));

    // Placeholder covers and typed text (typewriter with a blinking caret).
    for (nm in T) {
        if (nm.indexOf("cover") !== 0) continue;
        var cv = desk(shape(main, "Field " + nm.substr(5), "rect", 10, 10, 8, { fill: T[nm].extra.color }));
        keyed2(sizeOf(cv), T[nm].w, T[nm].h, function (w, h) { return [w, h]; });
        position(cv, T[nm].cx, T[nm].cy);
        opacity(cv, T[nm].o);
    }
    for (nm in T) {
        if (nm.indexOf("typed") !== 0) continue;
        var ty = T[nm], txt = ty.extra.text, sz = ty.extra.size;
        var mw = ty.mw, t0 = null, t1 = null, maxv = 0, q;
        for (q = 0; q < mw.length; q++) maxv = Math.max(maxv, mw[q][1]);
        for (q = 0; q < mw.length; q++) { if (t0 === null && mw[q][1] > 0.5) t0 = (q > 0 ? mw[q - 1][0] : mw[q][0]) / FPS; if (t1 === null && mw[q][1] >= maxv - 0.5) t1 = mw[q][0] / FPS; }
        if (t0 === null) continue;
        var TL = desk(text(main, "Typing " + nm.substr(5), txt, hasBangla(txt) ? FONT.bnMedium : FONT.en, sz, "#1f1f22", null));
        position(TL, ty.x, ty.y, null, function (v) { return v + sz * 1.05; });
        opacity(TL, ty.o);
        var esc = txt.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
        TL.property("ADBE Text Properties").property("ADBE Text Document").expression =
            'var s = "' + esc + '";\n' +
            "var t0 = " + t0.toFixed(3) + ", t1 = " + t1.toFixed(3) + ";\n" +
            "var n = Math.floor(linear(time, t0, t1, 0, s.length) + 0.0001);\n" +
            'var caret = (time >= t0 && time < t1 + 0.8 && Math.floor(time * 2.5) % 2 == 0) ? "|" : "";\n' +
            "s.substr(0, n) + caret";
    }

    // Highlight rings.
    for (nm in T) {
        if (nm.indexOf("ring") !== 0) continue;
        var R = desk(shape(main, "Highlight " + nm.substr(4), "rect", 10, 10, 14, { stroke: "#f5c76c", strokeW: 4 }));
        var glow = R.property("ADBE Root Vectors Group").property(1).property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
        glow.property("ADBE Vector Stroke Color").setValue(hex("#f5c76c"));
        glow.property("ADBE Vector Stroke Width").setValue(14);
        glow.property("ADBE Vector Stroke Opacity").setValue(25);
        keyed2(sizeOf(R), T[nm].w, T[nm].h, function (w, h) { return [w, h]; });
        position(R, T[nm].cx, T[nm].cy);
        keyed(tr(R).property("ADBE Scale"), T[nm].s, function (v) { return [v * 100, v * 100]; });
        opacity(R, T[nm].o);
    }

    // Click ripple and the pointer (your blue cursor; tip at pixel 72,45 of the 700 px image).
    var rip = desk(shape(main, "Click ripple", "ellipse", 60, 60, 0, { stroke: "#f5c76c", strokeW: 4 }));
    position(rip, T["ripple"].x, T["ripple"].y);
    keyed(tr(rip).property("ADBE Scale"), T["ripple"].s, function (v) { return [v * 100, v * 100]; });
    opacity(rip, T["ripple"].o);
    var cur = desk(place(main, footage("cursor.png"), "Cursor", [72, 45], null, 8));
    position(cur, T["cursor"].x, T["cursor"].y);
    keyed(tr(cur).property("ADBE Scale"), T["cursor"].s, function (v) { return [v * 8, v * 8]; });
    opacity(cur, T["cursor"].o);
    shadow(cur, 60, 6, 14);

    // Camera keys go on last, after everything is parented to it.
    position(cam, T["world"].x, T["world"].y);
    keyed(tr(cam).property("ADBE Scale"), T["world"].s, function (v) { return [v * 100, v * 100]; });

    // ---------------- screen-fixed layers ----------------
    place(main, footage("vant-mark-white.png"), "Logo (corner)", [0, 0], [46, 38], 14.5);
    tr(main.layer(1)).property("ADBE Opacity").setValue(92);

    // Pop-up notifications.
    for (nm in T) {
        if (nm.indexOf("toast") !== 0) continue;
        var tt = T[nm], tx = tt.extra;
        var nul = main.layers.addNull(DUR);
        nul.name = "Notification " + nm.substr(5);
        tr(nul).property("ADBE Anchor Point").setValue([0, 0]);
        tr(nul).property("ADBE Position").setValue([660, 48]);
        var parts = [
            shape(main, nul.name + " card", "rect", 600, 92, 26, { fill: "#ffffff", fillOpacity: 93, at: [300, 46] }),
            shape(main, nul.name + " icon", "rect", 52, 52, 15, { fill: tx.color, at: [46, 46] }),
            text(main, nul.name + " symbol", tx.icon, hasBangla(tx.icon) ? FONT.bnBold : FONT.enSemi, 28, "#ffffff", [46, 56], { center: true }),
            text(main, nul.name + " title", tx.t1, hasBangla(tx.t1) ? FONT.bnBold : FONT.enSemi, 23, "#1d1d1f", [90, 40]),
            text(main, nul.name + " detail", tx.t2, hasBangla(tx.t2) ? FONT.bnMedium : FONT.en, 18, "#6e6e73", [90, 68])
        ];
        shadow(parts[0], 55, 24, 60);
        for (var pi = 0; pi < parts.length; pi++) {
            var pos = tr(parts[pi]).property("ADBE Position").value;
            parts[pi].parent = nul;
            tr(parts[pi]).property("ADBE Position").setValue([pos[0], pos[1]]);
            opacity(parts[pi], tt.o);
        }
        position(nul, still(660), tt.y, null, function (v) { return 48 + v; });
    }

    // Subtitles: one text layer whose text changes line by line; words light up through a text animator.
    var subT = text(main, "Subtitle text", " ", FONT.bn, 38, "#857a7d", [960, 992], { center: true });
    var src = subT.property("ADBE Text Properties").property("ADBE Text Document");
    var base = src.value;
    var sTimes = [], sDocs = [], oList = [[0, 0]], ends = [], endsV = [];
    for (var si = 0; si < D.subs.length; si++) {
        var sub = D.subs[si], words = [];
        for (var w = 0; w < sub.words.length; w++) words.push(sub.words[w].text);
        base.text = words.join(" ");
        sTimes.push(sub.on); sDocs.push(base);
        base = src.value;
        oList.push([Math.round(sub.on * FPS), 1]);
        oList.push([Math.round(sub.off * FPS), 0]);
        ends.push(sub.on); endsV.push(0);
        for (w = 0; w < sub.words.length; w++) { ends.push(Math.max(sub.on + 0.001, sub.words[w].t)); endsV.push(pct((w + 1) / sub.words.length * 100)); }
    }
    src.setValuesAtTimes(sTimes, sDocs);
    var op = tr(subT).property("ADBE Opacity");
    keyed(op, oList, function (v) { return pct(v * 100); });
    holdAll(op);
    var anim = subT.property("ADBE Text Properties").property("ADBE Text Animators").addProperty("ADBE Text Animator");
    anim.name = "Spoken words";
    anim.property("ADBE Text Animator Properties").addProperty("ADBE Text Fill Color").setValue([1, 1, 1]);
    var sel = anim.property("ADBE Text Selectors").addProperty("ADBE Text Selector");
    sel.property("ADBE Text Range Advanced").property("ADBE Text Range Type2").setValue(3);   // based on words
    var endP = sel.property("ADBE Text Percent End");
    endP.setValuesAtTimes(ends, endsV);
    holdAll(endP);
    var pill = shape(main, "Subtitle pill", "rect", 100, 60, 34, { fill: "#1a060a", fillOpacity: 82, stroke: "#ffffff", strokeOpacity: 14, strokeW: 1.5 });
    pill.moveAfter(subT);
    sizeOf(pill).expression = 'var r = thisComp.layer("Subtitle text").sourceRectAtTime(time, false);\n[r.width + 68, r.height + 26]';
    tr(pill).property("ADBE Position").expression = 'var L = thisComp.layer("Subtitle text"); var r = L.sourceRectAtTime(time, false);\nL.toComp([r.left + r.width / 2, r.top + r.height / 2])';
    tr(pill).property("ADBE Opacity").expression = 'thisComp.layer("Subtitle text").transform.opacity';
    shadow(pill, 60, 18, 40);

    // End card.
    var end = solid(main, "End card", "#6b1f2e", 1920, 1080);
    ramp(end, [960, 486], "#6b1f2e", [960 + 1150, 486], "#1c0509", true);
    opacity(end, T["end"].o);
    var logo = place(main, footage("vant-logo-white.png"), "End logo", [600, 200], [960, 400], 50);
    keyed(tr(logo).property("ADBE Scale"), T["endLogo"].s, function (v) { return [v * 50, v * 50]; });
    opacity(logo, T["endLogo"].o);
    var endTag = text(main, "End tagline", "GENUINE LEATHER. TIMELESS STYLE.", FONT.en, 30, "#ffffff", [960, 552], { center: true, tracking: 200 });
    position(endTag, still(960), T["endTag"].y, null, function (v) { return 552 + v; });
    opacity(endTag, T["endTag"].o, 0.85);
    var endLine = shape(main, "End line", "rect", 120, 2, 0, { fill: "#ffffff", fillOpacity: 35 });
    position(endLine, still(960), T["endLine"].y, null, function (v) { return 591 + v; });
    opacity(endLine, T["endLine"].o);
    var endHelp = text(main, "End help line", "সাহায্যের জন্য: 01775-075543", FONT.bnMedium, 30, "#ffffff", [960, 652], { center: true });
    position(endHelp, still(960), T["endHelp"].y, null, function (v) { return 652 + v; });
    opacity(endHelp, T["endHelp"].o, 0.75);
    var thanks = text(main, "End thanks", "ধন্যবাদ", FONT.bnBold, 64, "#ffffff", [960, 768], { center: true });
    position(thanks, still(960), T["endThanks"].y, null, function (v) { return 768 + v; });
    opacity(thanks, T["endThanks"].o);

    // Voiceover.
    if (D.audio) main.layers.add(footage("voiceover.mp3")).name = "Voiceover";

    main.openInViewer();
    app.endUndoGroup();
    alert("Vant admin tutorial is ready: " + main.numLayers + " layers in \"" + main.name + "\".\n\nMove the camera with the \"CAMERA (move me)\" null.");
})();
